INSERT INTO plan_prices(public_id,plan_id,amount,currency,billing_type,is_active,valid_from,created_at) SELECT CONCAT('2',LPAD(id,31,'0')),id,CASE slug WHEN 'gratis' THEN 0 WHEN 'basic-30' THEN 49000 WHEN 'intensif-30' THEN 99000 WHEN 'pro-90' THEN 249000 WHEN 'token-full-1' THEN 15000 WHEN 'token-full-5' THEN 59000 WHEN 'token-full-10' THEN 99000 ELSE 0 END,'IDR',IF(slug='institusi','quote','one_time'),1,'2026-01-01 00:00:00',UTC_TIMESTAMP() FROM subscription_plans;
INSERT INTO plan_features(public_id,entitlement_key,name,sort_order,created_at) VALUES
('30000000000000000000000000000001','daily_question_limit','Batas soal harian',10,UTC_TIMESTAMP()),('30000000000000000000000000000002','monthly_question_limit','Batas soal bulanan',20,UTC_TIMESTAMP()),('30000000000000000000000000000003','total_question_limit','Batas total soal',30,UTC_TIMESTAMP()),('30000000000000000000000000000004','mini_tryout_limit','Batas mini tryout',40,UTC_TIMESTAMP()),('30000000000000000000000000000005','full_tryout_limit','Batas full tryout',50,UTC_TIMESTAMP()),('30000000000000000000000000000006','bookmark_limit','Batas bookmark',60,UTC_TIMESTAMP()),('30000000000000000000000000000007','history_retention_days','Retensi riwayat',70,UTC_TIMESTAMP()),('30000000000000000000000000000008','explanation_access','Akses pembahasan',80,UTC_TIMESTAMP()),('30000000000000000000000000000009','advanced_topic_analytics','Analitik topik',90,UTC_TIMESTAMP()),('30000000000000000000000000000010','difficulty_analytics','Analitik difficulty',100,UTC_TIMESTAMP()),('30000000000000000000000000000011','time_analytics','Analitik waktu',110,UTC_TIMESTAMP()),('30000000000000000000000000000012','wrong_answer_practice','Latihan soal salah',120,UTC_TIMESTAMP()),('30000000000000000000000000000013','adaptive_recommendation','Rekomendasi adaptif',130,UTC_TIMESTAMP()),('30000000000000000000000000000014','ad_free','Tanpa banner promosi',140,UTC_TIMESTAMP()),('30000000000000000000000000000015','tryout_token_balance','Saldo token tryout',150,UTC_TIMESTAMP());
INSERT INTO plan_feature_values(plan_id,feature_id,value_type,integer_value,boolean_value,string_value,created_at)
SELECT p.id,f.id,IF(f.entitlement_key IN ('explanation_access'),'string',IF(f.entitlement_key IN ('advanced_topic_analytics','difficulty_analytics','time_analytics','wrong_answer_practice','adaptive_recommendation','ad_free'),'boolean','integer')),
CASE f.entitlement_key WHEN 'daily_question_limit' THEN IF(p.slug='gratis',15,NULL) WHEN 'monthly_question_limit' THEN IF(p.slug='gratis',100,NULL) WHEN 'total_question_limit' THEN CASE p.slug WHEN 'basic-30' THEN 2000 WHEN 'intensif-30' THEN 10000 WHEN 'pro-90' THEN 30000 END WHEN 'mini_tryout_limit' THEN CASE p.slug WHEN 'gratis' THEN 1 WHEN 'basic-30' THEN 5 WHEN 'intensif-30' THEN 20 WHEN 'pro-90' THEN 60 END WHEN 'full_tryout_limit' THEN CASE p.slug WHEN 'basic-30' THEN 1 WHEN 'intensif-30' THEN 5 WHEN 'pro-90' THEN 15 END WHEN 'bookmark_limit' THEN CASE p.slug WHEN 'gratis' THEN 20 WHEN 'basic-30' THEN 500 ELSE -1 END WHEN 'history_retention_days' THEN CASE p.slug WHEN 'gratis' THEN 30 WHEN 'basic-30' THEN 30 WHEN 'intensif-30' THEN 30 WHEN 'pro-90' THEN 90 END WHEN 'tryout_token_balance' THEN CASE p.slug WHEN 'token-full-1' THEN 1 WHEN 'token-full-5' THEN 5 WHEN 'token-full-10' THEN 10 END END,
CASE WHEN f.entitlement_key='ad_free' THEN p.slug IN ('intensif-30','pro-90') WHEN f.entitlement_key='adaptive_recommendation' THEN p.slug='pro-90' WHEN f.entitlement_key IN ('advanced_topic_analytics','difficulty_analytics','time_analytics') THEN p.slug IN ('intensif-30','pro-90') WHEN f.entitlement_key='wrong_answer_practice' THEN p.slug IN ('basic-30','intensif-30','pro-90') END,
CASE WHEN f.entitlement_key='explanation_access' THEN IF(p.slug='gratis','limited','full') END,UTC_TIMESTAMP()
FROM subscription_plans p CROSS JOIN plan_features f WHERE p.slug<>'institusi' AND ((p.plan_type='token' AND f.entitlement_key IN ('tryout_token_balance','explanation_access')) OR (p.plan_type='subscription' AND f.entitlement_key<>'tryout_token_balance'));
